using System;
using System.IO;
using System.Linq;
using System.Text;
namespace JingFamily {
 public static class Reports {
  public static void ExportHtml(string path){var d=Store.Data;var b=new StringBuilder("<!doctype html><html lang='zh-CN'><meta charset='utf-8'>"+BrandMark.HtmlHead()+"<meta name='viewport' content='width=device-width,initial-scale=1'><title>"+Store.X(d.Title)+"</title><style>body{font:16px 'Microsoft YaHei',sans-serif;color:#27342e;background:#f7f6f1;max-width:1000px;margin:50px auto;padding:20px}h1,h2{color:#1d4b3d}header{border-bottom:3px solid #b28b48;padding-bottom:20px}article{background:white;border:1px solid #ddd;padding:22px;margin:20px 0;break-inside:avoid}p{line-height:1.8;white-space:pre-wrap}small{color:#777}nav a{display:inline-block;margin:6px;color:#1d4b3d}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #ddd}@media print{body{margin:0;background:white}nav,.print{display:none}article{page-break-inside:avoid}}</style><header>"+BrandMark.HtmlImage(56)+"<h1>"+Store.X(d.Title)+"</h1><p>"+Store.X(d.Motto)+"</p><small>编印日期 "+DateTime.Now.ToString("yyyy-MM-dd")+" · 成员 "+d.People.Count+" 人</small></header><p>"+Store.X(d.History)+"</p><button class='print' onclick='window.print()'>打印 / 另存为 PDF</button><h2>成员索引</h2><nav>");foreach(var p in d.People)b.Append("<a href='#p"+Store.X(p.Id)+"'>"+Store.X(p.Name)+"</a>");b.Append("</nav>");foreach(var p in d.People){b.Append("<article id='p"+Store.X(p.Id)+"'><h2>"+Store.X(p.Name)+" <small>"+Store.X(p.Gender)+"</small></h2><p>生卒："+Store.X(Ui.DateLabel(p.Birth))+" — "+Store.X(Ui.DateLabel(p.Death))+"\n籍贯："+Store.X(p.Place)+"　字辈："+Store.X(p.Generation)+"\n职业："+Store.X(p.Occupation)+"\n父亲："+Store.X(Store.Name(p.FatherId))+"　母亲："+Store.X(Store.Name(p.MotherId))+"\n配偶："+Store.X(String.Join("、",p.Spouses.Select(Store.Name)))+"\n子女："+Store.X(String.Join("、",d.People.Where(x=>x.FatherId==p.Id||x.MotherId==p.Id).Select(x=>x.Name)))+"</p><p>"+Store.X(p.Biography)+"</p></article>");}b.Append("<h2>家族大事记</h2><table><tr><th>日期</th><th>事件</th><th>记录</th></tr>");foreach(var e in d.Events.OrderBy(x=>x.Date))b.Append("<tr><td>"+Store.X(e.Date)+"</td><td>"+Store.X(e.Title)+"</td><td>"+Store.X(e.Place+" "+e.Notes)+"</td></tr>");b.Append("</table><p><small>由景·谱 1.5 生成 · 微信公众号：景同志 · 小红书：景同学</small></p></html>");System.IO.File.WriteAllText(path,b.ToString(),new UTF8Encoding(false));}
 }
}
